/**
 * @suppress
 */
public object FfiConverterTypeImprovMobileEngine: FfiConverter<ImprovMobileEngine, Pointer> {

    override fun lower(value: ImprovMobileEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): ImprovMobileEngine {
        return ImprovMobileEngine(value)
    }

    override fun read(buf: ByteBuffer): ImprovMobileEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ImprovMobileEngine) = 8UL

    override fun write(value: ImprovMobileEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



