/**
 * FFI error type surfaced as an exception in Kotlin.
 */
sealed class ImprovFfiException(message: String): kotlin.Exception(message) {
        
        class Message(message: String) : ImprovFfiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ImprovFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): ImprovFfiException = FfiConverterTypeImprovFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeImprovFfiError : FfiConverterRustBuffer<ImprovFfiException> {
    override fun read(buf: ByteBuffer): ImprovFfiException {
        
            return when(buf.getInt()) {
            1 -> ImprovFfiException.Message(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: ImprovFfiException): ULong {
        return 4UL
    }

    override fun write(value: ImprovFfiException, buf: ByteBuffer) {
        when(value) {
            is ImprovFfiException.Message -> {
                buf.putInt(1)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceDouble: FfiConverterRustBuffer<List<kotlin.Double>> {
    override fun read(buf: ByteBuffer): List<kotlin.Double> {
        val len = buf.getInt()
        return List<kotlin.Double>(len) {
            FfiConverterDouble.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.Double>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterDouble.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.Double>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterDouble.write(it, buf)
        }
    }
}




